use std::{
    collections::{BTreeMap, HashSet},
    env, fs,
};

use anyhow::{ensure, Result};
use toml::Table;

use crate::{
    schema::{Group, Language},
    LANGUAGE_CONFIG,
};

mod js_lists;
mod js_pkgs;
mod parser_lists;
mod parsers_dep;
mod parsers_git;
mod parsers_gitdep;
mod queries;
mod theme_list;

const TOML_AUTOGEN_HEADER: &str = "
###########################################
### All following code is autogenerated ###
### by running `cargo xtask codegen` in ###
### the verdant workspace. #############
###########################################
";
const TOML_FEATURES_HEAD: &str = r##"
[features]
#! ### Features
default = []
"##;
const TOML_FEATURES_INTRO: &str = r##"
#! Most languages have a feature with the same name as the respective public function. To stay
#! within crates.io's limit of 300 features per crate, less common languages are only enabled by
#! the feature of their language family (listed below) or by `all`, and languages that share a
#! parser repository (like `typescript` and `tsx`) share one feature. The README of this crate
#! names the feature that enables each language.
#!
#! Additionally the three feature groups
#! <span class="stab portability"><code>some</code></span>,
#! <span class="stab portability"><code>most</code></span>, and
#! <span class="stab portability"><code>all</code></span>
#! are available.

## Include parsers for the most widely known supported languages.
"##;
const TOML_FEATURES_FAMILIES: &str = r##"
#! ### Language families
#! Each of these features enables a family of related languages.
"##;
const TOML_FEATURES_MOST: &str = r##"
## Implies <span class="stab portability"><code>some</code></span>.
## Include parsers for most common languages.
"##;
const TOML_FEATURES_ALL: &str = r##"
## Implies <span class="stab portability"><code>most</code></span>.
## Include parsers for all supported languages.
"##;
const TOML_FEATURES_DOCS: &str = r##"
## Meant to be enabled when building docs
docs = ["dep:document-features", "dep:rustc_version"]

"##;

fn is_arg(test: &str) -> bool {
    env::args().nth(2).map_or(true, |arg| arg == test)
}

pub fn run() -> Result<()> {
    if is_arg("queries") {
        let mut queries_lib_rs = r###"
#![doc = include_str!("../README.md")]
#![cfg_attr(docsrs, feature(doc_cfg))]
#![cfg_attr(rustfmt, rustfmt_skip)]
"###
        .trim_start()
        .to_owned();

        let queries_dir = crate::WORKSPACE_DIR.join("syntastica-queries/generated_queries");
        let _ = fs::remove_dir_all(&queries_dir);
        fs::create_dir_all(&queries_dir)?;
        fs::write(
            queries_dir.join("README.md"),
            include_str!("./codegen/generated_queries_readme.md"),
        )?;

        for (
            ref name,
            [highlights, injections, locals, highlights_crates_io, injections_crates_io, locals_crates_io],
        ) in queries::make_queries()?
        {
            let lang_dir = queries_dir.join(name);
            fs::create_dir(&lang_dir)?;

            fs::write(lang_dir.join("highlights.scm"), highlights)?;
            fs::write(lang_dir.join("injections.scm"), injections)?;
            fs::write(lang_dir.join("locals.scm"), locals)?;
            fs::write(
                lang_dir.join("highlights_crates_io.scm"),
                highlights_crates_io,
            )?;
            fs::write(
                lang_dir.join("injections_crates_io.scm"),
                injections_crates_io,
            )?;
            fs::write(lang_dir.join("locals_crates_io.scm"), locals_crates_io)?;

            queries_lib_rs += &format!(
                r###"
pub const {lang}_HIGHLIGHTS: &str = include_str!("../generated_queries/{name}/highlights.scm");
pub const {lang}_INJECTIONS: &str = include_str!("../generated_queries/{name}/injections.scm");
pub const {lang}_LOCALS: &str = include_str!("../generated_queries/{name}/locals.scm");
pub const {lang}_HIGHLIGHTS_CRATES_IO: &str = include_str!("../generated_queries/{name}/highlights_crates_io.scm");
pub const {lang}_INJECTIONS_CRATES_IO: &str = include_str!("../generated_queries/{name}/injections_crates_io.scm");
pub const {lang}_LOCALS_CRATES_IO: &str = include_str!("../generated_queries/{name}/locals_crates_io.scm");
"###,
                lang = name.to_uppercase()
            )
        }
        fs::write(
            crate::WORKSPACE_DIR.join("syntastica-queries/src/lib.rs"),
            queries_lib_rs,
        )?;
    }

    if is_arg("parsers-dep") {
        parsers_dep::write()?;
    }

    if is_arg("parsers-gitdep") {
        parsers_gitdep::write()?;
    }

    if is_arg("parsers-git") {
        parsers_git::write()?;
    }

    if is_arg("parser-lists") {
        parser_lists::write()?;
    }

    if is_arg("js-list") {
        js_lists::write()?;
    }

    if is_arg("js-pkgs") {
        js_pkgs::write()?;
    }

    if is_arg("theme-list") {
        theme_list::write()?;
    }

    Ok(())
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum ParserCollection {
    Git,
    GitDep,
    Dep,
}

/// A language together with the languages bundled with it, which one feature enables.
fn bundle(owner: &Language) -> Vec<&Language> {
    LANGUAGE_CONFIG
        .languages
        .iter()
        .filter(|lang| {
            lang.name == owner.name || lang.bundled_with.as_deref() == Some(owner.name.as_str())
        })
        .collect()
}

/// The languages naming each family in `family`, in `languages.toml` order.
fn families() -> BTreeMap<&'static str, Vec<&'static Language>> {
    let mut families: BTreeMap<_, Vec<_>> = BTreeMap::new();
    for lang in &LANGUAGE_CONFIG.languages {
        if let Some(family) = &lang.family {
            families.entry(family.as_str()).or_default().push(lang);
        }
    }
    families
}

/// The `dep:` entries pulling in the parsers `collection` has for `lang` and its bundle.
fn dep_features(lang: &Language, collection: ParserCollection) -> Vec<String> {
    let mut deps = vec![];
    if collection != ParserCollection::Git {
        for member in bundle(lang) {
            let dep = format!("dep:{}", member.parser.package);
            if member
                .parser
                .supports(collection == ParserCollection::GitDep)
                && !deps.contains(&dep)
            {
                deps.push(dep);
            }
        }
    }
    deps
}

fn parsers_toml_feature(group: Group) -> String {
    let mut feature_str = format!("{group} = [\n");
    if let Some(group) = group.next_smaller() {
        feature_str += &format!("    \"{group}\",\n");
    }
    if group == Group::All {
        for family in families().keys() {
            feature_str += &format!("    \"{family}\",\n");
        }
    }
    let mut seen = HashSet::new();
    for lang in LANGUAGE_CONFIG
        .languages
        .iter()
        .filter(|lang| lang.group == group && LANGUAGE_CONFIG.has_own_feature(lang))
    {
        if !seen.insert(lang.name.clone()) {
            continue;
        }
        feature_str += "    \"";
        feature_str += &lang.name;
        feature_str += "\",\n";
    }
    feature_str + "]\n"
}

/// Wraps the names of a family's languages into documentation comment lines.
fn family_doc(names: &[&str]) -> String {
    let mut lines = vec![String::from(
        "## Include parsers for the languages of this family:",
    )];
    for (i, name) in names.iter().enumerate() {
        let end = if i + 1 == names.len() { "." } else { "," };
        let line = lines.last_mut().expect("`lines` starts non-empty");
        if line.len() + name.len() + 2 > 100 {
            lines.push(format!("## {name}{end}"));
        } else {
            *line += &format!(" {name}{end}");
        }
    }
    lines.join("\n") + "\n"
}

fn parsers_toml_family_features(collection: ParserCollection) -> String {
    let mut out = String::from(TOML_FEATURES_FAMILIES);
    for (family, owners) in families() {
        let names = owners
            .iter()
            .flat_map(|owner| bundle(owner))
            .map(|lang| lang.name.as_str())
            .collect::<Vec<_>>();
        out += "\n";
        out += &family_doc(&names);

        // owners with their own feature are enabled through it, all others directly
        let mut entries = vec![];
        for owner in owners {
            if LANGUAGE_CONFIG.has_own_feature(owner) {
                entries.push(owner.name.clone());
            } else {
                entries.extend(dep_features(owner, collection));
            }
        }
        out += &format!("{family} = [");
        for entry in &entries {
            out += &format!("\n    \"{entry}\",");
        }
        out += if entries.is_empty() { "]\n" } else { "\n]\n" };
    }
    out
}

fn parsers_toml_lang_features(collection: ParserCollection) -> String {
    let mut out = String::new();
    let mut seen = HashSet::new();
    for lang in &LANGUAGE_CONFIG.languages {
        if !seen.insert(lang.name.clone()) || !LANGUAGE_CONFIG.has_own_feature(lang) {
            continue;
        }
        out += &lang.name;
        out += " = [";
        out += &dep_features(lang, collection)
            .iter()
            .map(|dep| format!("\"{dep}\""))
            .collect::<Vec<_>>()
            .join(", ");
        out += "]\n";
    }
    out
}

fn parsers_toml_deps(toml: &mut String, git: bool) {
    let mut added_packages = vec![];
    for lang in crate::LANGUAGE_CONFIG
        .languages
        .iter()
        .filter(|lang| lang.parser.supports(git))
    {
        let package = &lang.parser.package;
        let url = &lang.parser.git.url;
        let rev = &lang.parser.git.rev;

        if added_packages.contains(&package) {
            continue;
        }
        added_packages.push(package);

        let dep_str = if git {
            format!(
                r##"
[dependencies.{package}]
optional = true
git = "{url}"
rev = "{rev}"
"##
            )
        } else {
            format!(
                r##"
[dependencies.{package}]
optional = true
version = "={version}"
"##,
                version = lang
                    .parser
                    .crates_io
                    .as_ref()
                    .expect("`None` is filtered above if `git` is `false`")
            )
        };
        *toml += &dep_str;
    }
}

/// crates.io rejects a crate declaring more `[features]` than this.
const CRATES_IO_MAX_FEATURES: usize = 300;

/// Fail codegen instead of the tag-triggered publish job when a manifest is over the limit.
fn check_crates_io_feature_limit(toml: &str, package: &str) -> Result<()> {
    let manifest = toml.parse::<Table>()?;
    let count = manifest
        .get("features")
        .and_then(|features| features.as_table())
        .map_or(0, Table::len);
    ensure!(
        count <= CRATES_IO_MAX_FEATURES,
        "`{package}` declares {count} features but crates.io allows at most \
         {CRATES_IO_MAX_FEATURES}; put more languages into families (`family` in \
         `syntastica-macros/languages.toml`)"
    );
    Ok(())
}
